package tcap

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"github.com/gomaja/go-asn1/telecom/ss7/tcap/runtime/ber"
	"testing"
)

// X.690 (02/2021) §§8.14.3, 8.18.1; X.680 (02/2021) §31.2.7 b).
// These profile-owned EXTERNALs retain their typed diagnostics and prefix.
func TestAssociatedExplicitProfileDiagnostics(t *testing.T) {
	var rows []struct {
		ID, Root, Hex             string
		Tolerant                  bool
		Scan, Error, Path, Prefix string
		Sentinels                 []bool
		Report                    any
	}
	if err := json.Unmarshal([]byte(associatedExplicitProfileBaseline), &rows); err != nil {
		t.Fatal(err)
	}
	for _, row := range rows {
		t.Run(fmt.Sprintf("%s/tolerant-%t", row.ID, row.Tolerant), func(t *testing.T) {
			wire, err := hex.DecodeString(row.Hex)
			if err != nil {
				t.Fatal(err)
			}
			var opts []ber.DecodeOption
			log := new(ber.ViolationLog)
			if row.Tolerant {
				opts = append(opts, ber.WithTolerance(log))
			}
			opts = ber.TrackTCAPForm(opts, row.Root)
			scan := ber.ValidateBERElement(wire, opts...)
			value := associatedProfileCodecFor(row.Root)
			err = value.UnmarshalBER(wire, opts...)
			var de *DecodeError
			errors.As(err, &de)
			path := ""
			var prefix any
			if de != nil {
				path = de.Path
				prefix = de.Prefix
			}
			raw, e := json.Marshal(prefix)
			if e != nil {
				t.Fatal(e)
			}
			if got := fmt.Sprintf("%x", sha256.Sum256(raw)); got != row.Prefix {
				t.Errorf("prefix=%s want %s", got, row.Prefix)
			}
			if fmt.Sprint(scan) != row.Scan || fmt.Sprint(err) != row.Error || path != row.Path {
				t.Errorf("scan=%v error=%v path=%q; want scan=%s error=%s path=%q", scan, err, path, row.Scan, row.Error, row.Path)
			}
			for i, sent := range []error{ber.ErrTruncated, ber.ErrInvalidTag, ber.ErrUnexpectedElement, ber.ErrInvalidLength, ber.ErrIndefiniteLength, ber.ErrExtraData, ber.ErrInvalidValue, ber.ErrUnsupported, ber.ErrResourceLimit} {
				if errors.Is(err, sent) != row.Sentinels[i] {
					t.Errorf("errors.Is(%v)=%t want %t", sent, errors.Is(err, sent), row.Sentinels[i])
				}
			}
			got, _ := json.Marshal(log.Snapshot())
			want, _ := json.Marshal(row.Report)
			if string(got) != string(want) {
				t.Errorf("report=%s want %s", got, want)
			}
		})
	}
}

type associatedProfileCodec interface {
	UnmarshalBER([]byte, ...ber.DecodeOption) error
}

func associatedProfileCodecFor(root string) associatedProfileCodec {
	switch root {
	case "AAREApdu":
		return new(AAREApdu)
	case "AARQApdu":
		return new(AARQApdu)
	case "ABRTApdu":
		return new(ABRTApdu)
	case "AUDTApdu":
		return new(AUDTApdu)
	case "Abort":
		return new(Abort)
	case "AbortReason":
		return new(AbortReason)
	case "AssociateSourceDiagnostic":
		return new(AssociateSourceDiagnostic)
	case "Begin":
		return new(Begin)
	case "Bind":
		return new(Bind)
	case "Code":
		return new(Code)
	case "Component":
		return new(Component)
	case "ComponentPortion":
		return new(ComponentPortion)
	case "Continue":
		return new(Continue)
	case "DialoguePDU":
		return new(DialoguePDU)
	case "DialoguePortion":
		return new(DialoguePortion)
	case "End":
		return new(End)
	case "Invoke":
		return new(Invoke)
	case "InvokeId":
		return new(InvokeId)
	case "InvokeLinkedId":
		return new(InvokeLinkedId)
	case "RLREApdu":
		return new(RLREApdu)
	case "RLRQApdu":
		return new(RLRQApdu)
	case "ROS":
		return new(ROS)
	case "ROSConsumerAS":
		return new(ROSConsumerAS)
	case "ROSSingleAS":
		return new(ROSSingleAS)
	case "ROSSupplierAS":
		return new(ROSSupplierAS)
	case "Reject":
		return new(Reject)
	case "RejectProblemChoice":
		return new(RejectProblemChoice)
	case "ReturnError":
		return new(ReturnError)
	case "ReturnResult":
		return new(ReturnResult)
	case "ReturnResultResult":
		return new(ReturnResultResult)
	case "TCInvokeIdSet":
		return new(TCInvokeIdSet)
	case "TCMessage":
		return new(TCMessage)
	case "Unbind":
		return new(Unbind)
	case "UniDialoguePDU":
		return new(UniDialoguePDU)
	case "Unidirectional":
		return new(Unidirectional)
	case "UserInformation":
		return new(UserInformation)
	}
	return nil
}

